//! The committed runtime configs' `config_hash` pins: `tests/fixtures/config_pins.json`, generated by
//! `scripts/pin_configs.py --write` from `scripts/cere_contracts.py` `canonical_digest` (`make validate` runs
//! `--check`), so the Rust loader's hash is checked against the Python one and a relock repins every test at once.
use std::collections::BTreeMap;
use std::path::Path;

/// Every `configs/runtime/*.toml` (its repository path) and its pinned `config_hash`.
pub fn config_hashes(root: &Path) -> BTreeMap<String, String> {
    let path = root.join("tests/fixtures/config_pins.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let mut doc: serde_json::Value = serde_json::from_str(&text).unwrap();
    serde_json::from_value(doc["config_hash"].take()).unwrap()
}
